head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05201";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — DeclPopupYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05201.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const frm = (document.SearchForm || { elements: [] });
        if ((String(((dma_pageContext.get("DeclPopupYn") ?? "")) == null ? '' : ((dma_pageContext.get("DeclPopupYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("DeclPopupYn") ?? "")) == null ? '' : ((dma_pageContext.get("DeclPopupYn") ?? "")))) === 'Y') {
            const _width = '900';
            const _height = '350';
            const _left = Math.ceil((screen.width - _width) / 2);
            const _top = Math.ceil((screen.height - _height) / 2);
            let _previewWindow;
            _previewWindow = $c.win.openPopup('', { id: "_frnTodayDeclYn_popup", scrollbars: false, resizable: false, type: "pageFramePopup" }, {});
            $c.util.getComponent('dma_searchListReq').set('method', 'popupFrnTodayDeclYnView');
            frm.action = '/event/event.do';
            frm.target = '_frnTodayDeclYn_popup';
            /* 수동 전환 필요: SearchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «SearchForm» 자기제출 — 대체 서버 호출 미정).");
        }
        if ("" + dma_companyInfoVO.get("isurCd") + "" === "99996") {
            await scwin.searchFileList();
        } else {
            await scwin.searchList();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05201.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: action ?? "/listeach/listeach.do",
        ref: "dma_searchListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchFileList
 * @description search File List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchFileList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchFileList",
        method: "post",
        action: action ?? "/upload/uploadFile.do",
        ref: "dma_searchFileListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    $c.util.getComponent('dma_searchListReq').set('method', "searchNonListingBondList");
    await scwin.tx_fn_searchList('/listeach/listeach.do');
};

/**
 * @method
 * @name searchFileList
 * @description search File List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFileList = async function () {
    $c.util.getComponent('dma_searchListReq').set('method', "uploadForm");
    await scwin.tx_fn_searchFileList('/upload/uploadFile.do');
};
